/* Frases con números, fechas o nombres */
const MESES = { ene: 'Jan', feb: 'Feb', mar: 'Mar', abr: 'Apr', may: 'May', jun: 'Jun', jul: 'Jul', ago: 'Aug', sept: 'Sep', sep: 'Sep', oct: 'Oct', nov: 'Nov', dic: 'Dec' };
const MESES_L = { enero: 'January', febrero: 'February', marzo: 'March', abril: 'April', mayo: 'May', junio: 'June', julio: 'July', agosto: 'August', septiembre: 'September', octubre: 'October', noviembre: 'November', diciembre: 'December' };
const fecha = t => t
  .replace(/\b(\d{1,2}) (ene|feb|mar|abr|may|jun|jul|ago|sept|sep|oct|nov|dic)\.?( \d{4})?\b/g, (m, d, me, a) => `${d} ${MESES[me]}${a || ''}`)
  .replace(/\b(\d{1,2}) de (enero|febrero|marzo|abril|mayo|junio|julio|agosto|septiembre|octubre|noviembre|diciembre)\b/g, (m, d, me) => `${MESES_L[me]} ${d}`);
const dias = n => `${n} day${n === '1' ? '' : 's'}`;

export const PATRONES = [
  [/^¡Hola, (.+)!$/, m => `Hi, ${m[1]}!`],
  [/^Cuesta (.+ €) al mes y se añade a tu pedido como cuota mensual\.$/, m => `It costs ${m[1]} a month and is added to your order as a monthly fee.`],
  [/^\+ (.+ €)\/mes de cuotas$/, m => `+ ${m[1]}/month in fees`],
  [/^Hacia el (.+)$/, m => `By ${m[1]}`],
  [/^Hoy, para empezar \((\d+) %\)$/, m => `Today, to start (${m[1]} %)`],
  [/^Entrega urgente \(\+(\d+) %\)$/, m => `Rush delivery (+${m[1]} %)`],
  [/^Bienvenida \(−(\d+) %\)$/, m => `Welcome (−${m[1]} %)`],
  [/^\+ (.+ €)\/mes de mantenimiento$/, m => `+ ${m[1]}/month maintenance`],
  [/^Te escribimos a (.+) cuando haya novedades\. Como mucho un correo cada 30 minutos por proyecto\.$/, m => `We email ${m[1]} when there is news. At most one email every 30 minutes per project.`],
  [/^pide otro en (0:\d\d)$/, m => `ask for another in ${m[1]}`],
  [/^Paso (\d+) de (\d+) · (.+)$/, (m, T) => `Step ${m[1]} of ${m[2]} · ${T(m[3])}`],
  [/^Paso (\d+) de (\d+)$/, m => `Step ${m[1]} of ${m[2]}`],
  [/^Paso (\d+): (.+)$/, (m, T) => `Step ${m[1]}: ${T(m[2])}`],
  [/^Faltan (\d+) días?$/, m => `${dias(m[1])} left`],
  [/^Retrasado (\d+) días?$/, m => `${dias(m[1])} late`],
  [/^Se entrega hoy$/, () => 'Due today'],
  [/^desde (.+ €)$/, m => `from ${m[1]}`],
  [/^Desde (.+ €)$/, m => `From ${m[1]}`],
  [/^(.+ €) en tu primera web$/, m => `${m[1]} on your first website`],
  [/^(\d+(?:\.\d+)?) de 5 estrellas$/, m => `${(+m[1]).toFixed(m[1].includes('.') ? 1 : 0)} out of 5 stars`],
  [/^Pedir (.+)$/, (m, T) => `Order ${T(m[1])}`],
  [/^Comprar (.+)$/, (m, T) => `Buy ${T(m[1].charAt(0).toUpperCase() + m[1].slice(1))}`],
  [/^Lista de espera: (.+)$/, (m, T) => `Waiting list: ${T(m[1])}`],
  [/^Ver diseño (.+)$/, m => `View ${m[1]} design`],
  [/^Diseño (\S+)$/, m => `${m[1]} design`],
  [/^Diseño (\S+) · (.+)$/, m => `${m[1]} design · ${m[2]}`],
  [/^Base imponible (.+) \+ IVA (\d+) %$/, m => `Tax base ${m[1]} + VAT ${m[2]} %`],
  [/^IVA incluido · base (.+) \+ IVA (\d+) % (.+)$/, m => `VAT included · base ${m[1]} + VAT ${m[2]} % ${m[3]}`],
  [/^Pagar señal de (.+)$/, m => `Pay deposit of ${m[1]}`],
  [/^Pagar (.+ €)(?: · (.+))?$/, m => `Pay ${m[1]}${m[2] ? ' · ' + m[2] : ''}`],
  [/^Toca pagar (.+)$/, m => `${m[1]} to pay`],
  [/^Añadido «(.+)» \(\+(.+)\)$/, (m, T) => `Added “${T(m[1])}” (+${m[2]})`],
  [/^Puedes desistir de este contrato sin dar explicaciones hasta el (.+)\.$/, m => `You can cancel this contract without giving a reason until ${fecha(m[1])}.`],
  [/^(\+ )?(.+ €)\/mes$/, m => `${m[1] || ''}${m[2]}/month`],
  [/^Ver tu diseño: (.+)$/, m => `See your design: ${m[1]}`],
  [/^Cuesta (.+ €) el primer año y se añade a tu pedido como extra\.$/, m => `It costs ${m[1]} for the first year and is added to your order as an extra.`],
  [/^Registrarlo con el alojamiento del primer año cuesta (.+ €) y se añade a tu pedido como extra\.$/, m => `Registering it with first-year hosting costs ${m[1]} and is added to your order as an extra.`],
  [/^Quitado «(.+)»: (.+)$/, (m, T) => `Removed “${T(m[1])}”: ${({ 'ya tienes dominio': 'you already have a domain', 'usarás Gmail': "you'll use Gmail" })[m[2]] || m[2]}`],
  [/^(\d+) de (\d+)$/, m => `${m[1]} of ${m[2]}`],
  [/^Etapa (\d+) de (\d+)$/, m => `Stage ${m[1]} of ${m[2]}`],
  [/^Tienes (\d+) proyectos:$/, m => `You have ${m[1]} projects:`],
  [/^Hola, (.+)\. Puedo decirte cómo va tu pedido, qué te toca pagar o enseñarte tu web, y resolver cualquier duda\.$/, m => `Hi, ${m[1]}. I can tell you how your order is going, what you need to pay or show you your website, and answer any question.`],
  [/^Hola\. Puedo decirte cómo va tu pedido, qué te toca pagar o enseñarte tu web, y resolver cualquier duda\.$/, () => 'Hi. I can tell you how your order is going, what you need to pay or show you your website, and answer any question.'],
  [/^Te toca: (.+)$/, (m, T) => `Your turn: ${T(m[1])}`],
  [/^(\d{1,2} \S+(?: \d{4})?) · faltan (\d+) días?$/, m => `${fecha(m[1])} · ${dias(m[2])} left`],
  [/^Precio final con el (\d+) % de IVA incluido\. Pago solo por transferencia bancaria\.$/, m => `Final price with ${m[1]} % VAT included. Bank transfer only.`],
  [/^Sector: (.+)$/, (m, T) => `Sector: ${T(m[1])}`],
  [/^Tipo: (.+)$/, (m, T) => `Type: ${T(m[1])}`],
  [/^Motivo: (.+)$/, (m, T) => `Reason: ${T(m[1])}`],
  [/^Plan (\d+): (.+)$/, (m, T) => `Plan ${m[1]}: ${T(m[2])}`],
  [/^(\d+) días?$/, m => dias(m[1])],
  [/^\+?(\d+) % sobre el precio base$/, m => `+${m[1]} % on the base price`],
  [/^Los precios de partida son: (.+)\. En el cuestionario puedes añadir extras y ves el total antes de confirmar\.$/, (m, T) => `Starting prices are: ${m[1].split('; ').map(x => x.replace(/^(.+): desde (.+)$/, (z, a, b) => `${T(a)}: from ${b}`)).join('; ')}. In the questionnaire you can add extras and see the total before confirming.`],
  [/^(\d{1,2} (?:ene|feb|mar|abr|may|jun|jul|ago|sept|sep|oct|nov|dic)\.?(?: \d{4})?)$/, m => fecha(m[1])],
  [/^(\d{1,2} de (?:enero|febrero|marzo|abril|mayo|junio|julio|agosto|septiembre|octubre|noviembre|diciembre))(.*)$/, m => fecha(m[1]) + m[2]]
];
